import{_ as s,o as n,c as t,a2 as o}from"./chunks/framework.mRCPFc5l.js";const b=JSON.parse('{"title":"08 · 持久化与工程化：如何管理 200+ 包的 monorepo","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/engineering.md","filePath":"deep-dive/engineering.md","lastUpdated":null}'),a={name:"deep-dive/engineering.md"};function r(i,e,p,l,c,d){return n(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="_08-·-持久化与工程化-如何管理-200-包的-monorepo" tabindex="-1">08 · 持久化与工程化：如何管理 200+ 包的 monorepo <a class="header-anchor" href="#_08-·-持久化与工程化-如何管理-200-包的-monorepo" aria-label="Permalink to &quot;08 · 持久化与工程化：如何管理 200+ 包的 monorepo&quot;">​</a></h1><blockquote><p>前面七章都在拆功能。这一章拆&quot;怎么做&quot;：monorepo 布局、双 face 构建（host/client）、Typert 类型图、测试体系、vendored Cordis 的本地修改日志、持久化后端。这些是&quot;工业级 agent 项目&quot;的必修课——也是面试中区分&quot;看过 demo&quot;与&quot;参与过真项目&quot;的部分。</p></blockquote><h2 id="_1-monorepo-布局-包名即角色" tabindex="-1">1. Monorepo 布局：包名即角色 <a class="header-anchor" href="#_1-monorepo-布局-包名即角色" aria-label="Permalink to &quot;1. Monorepo 布局：包名即角色&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vendor/       Vendored Cordis 源码（固定版本、可审计、可补丁）</span></span>
<span class="line"><span>packages/     @deepseek-ai/dsh-&lt;pkg&gt;，按 packages/&lt;group&gt;/&lt;pkg&gt;/ 组织</span></span>
<span class="line"><span>  core/        产品 API 脊柱（session/system-prompt/tools/agent/agent-loop/scope）</span></span>
<span class="line"><span>  api/         BFF 组装 + Typert RPC 网关</span></span>
<span class="line"><span>  typert/      类型图生成器、加载器、运行时注册表</span></span>
<span class="line"><span>  llm/         LLM 能力（Definition + Consumer + DeepSeek providers）</span></span>
<span class="line"><span>  shell/       bash 能力（Definition + local/pwsh providers + tool Consumer）</span></span>
<span class="line"><span>  subprocess/  subprocess 能力 + 本地进程树 provider</span></span>
<span class="line"><span>  fs/          文件系统能力 + 策略</span></span>
<span class="line"><span>  subagent/    子代理能力（Definition + providers + 委托 Consumer）</span></span>
<span class="line"><span>  workflow/    工作流能力 + worker-thread provider + tool Consumer</span></span>
<span class="line"><span>  ...</span></span>
<span class="line"><span>apps/         cli（dsh bin）、web（Vite 入口）</span></span>
<span class="line"><span>native/       Landlock launcher（C 源码）</span></span>
<span class="line"><span>python/       Python SDK + bundled runtime</span></span>
<span class="line"><span>examples/     可运行的 cordis.yml leaves</span></span>
<span class="line"><span>website/      VitePress 官方文档站</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><p>包名即角色：<code>dsh-shell</code>（Definition）、<code>dsh-bash-local</code>（Provider）、<code>dsh-tool-bash</code>（Consumer）——看名字就知道它在 seam 里的位置。这不是巧合，而是<strong>命名规则</strong>（见 <code>docs/cookbook/adding-a-package.md#name-the-role-that-exists</code>）：包名描述&quot;存在的角色&quot;，不超前描述。</p><h2 id="_2-构建-双-face-tsc-项目引用-tsdown" tabindex="-1">2. 构建：双 face + tsc 项目引用 + tsdown <a class="header-anchor" href="#_2-构建-双-face-tsc-项目引用-tsdown" aria-label="Permalink to &quot;2. 构建：双 face + tsc 项目引用 + tsdown&quot;">​</a></h2><p>构建管线分两步（<code>tsdown.config.ts</code>）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pnpm run build:lib:host     tsc -b tsconfig.host.json（类型+JS 中间产物）+ tsdown 打包 host 面</span></span>
<span class="line"><span>pnpm run build:lib:client   tsc -b tsconfig.client.json + tsdown --env.DSH_BUILD_FACE client</span></span>
<span class="line"><span>pnpm run build:web          Vite 构建 Web 前端</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>关键概念：</p><ul><li><strong>host/client 两个编译面</strong>：host 是 Node 运行时，client 是浏览器 bundle。<code>packages/client</code> 下的 UI 包在 client pass 里产出浏览器工件——<strong>同一个包，两套编译目标，通过 package.json exports 区分</strong></li><li><strong>源面与产物面分离</strong>：静态检查（tsc/lint/test）通过 tsconfig paths 解析到 <code>src</code>；消费构建产物的 gate 显式声明依赖 <code>lib/</code>。两者从不混用</li><li><strong>Typert 插件</strong>：host 构建时 <code>typertPlugin</code> 从源码生成<strong>类型图</strong>（type graph）——这是下一节的 RPC 基础</li><li>每个包的 tsconfig 都 <code>rootDir: src, outDir: lib/types</code>，引用每个 workspace 依赖 + <code>runtime-diagnostics/invariants</code></li></ul><h2 id="_3-typert-把类型变成运行时可消费的图" tabindex="-1">3. Typert：把类型变成运行时可消费的图 <a class="header-anchor" href="#_3-typert-把类型变成运行时可消费的图" aria-label="Permalink to &quot;3. Typert：把类型变成运行时可消费的图&quot;">​</a></h2><p><code>packages/typert/</code> 是 DSH 最有特色的基础设施：<strong>类型图生成器 + 加载器 + 运行时注册表</strong>。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tsc 编译 → JS 中间产物（lib/types）</span></span>
<span class="line"><span>typertPlugin → 从 JS + 类型元数据生成类型图（type graph）</span></span>
<span class="line"><span>运行时 → ctx.typert 注册表：查询 schema、反射元数据</span></span>
<span class="line"><span>API 网关 → ctx.typertGateway：把 Remote 描述符与实时 Cordis 服务关联</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>这解决了 monorepo 的经典问题：<strong>浏览器与宿主进程之间怎么共享类型安全</strong>。<code>api-gateway</code> 生成的 Remote 描述符与宿主服务关联，通过共享的 Connection RPC 载体提供一元调用——前端拿到的不是手写 API client，而是从类型图生成的、有运行时 schema 校验的调用描述符。</p><h2 id="_4-持久化-同一套事件词汇-多个后端" tabindex="-1">4. 持久化：同一套事件词汇，多个后端 <a class="header-anchor" href="#_4-持久化-同一套事件词汇-多个后端" aria-label="Permalink to &quot;4. 持久化：同一套事件词汇，多个后端&quot;">​</a></h2><p><code>ctx.sessionPersistence</code> seam 的两个后端（<code>packages/session/</code>）：</p><table tabindex="0"><thead><tr><th>后端</th><th>特性</th></tr></thead><tbody><tr><td><code>session-persistence-jsonl</code></td><td>JSONL 追加写；Windows 上经 koffi 调 <code>MoveFileExW</code> 做写透发布</td></tr><tr><td><code>session-persistence-sqlite</code></td><td>SQLite，单调 <code>SCHEMA_VERSION</code></td></tr></tbody></table><p>关键纪律（根 AGENTS.md）：</p><ul><li><strong>各后端持久化同一套 SessionEvent 词汇</strong>——应用在组合时选择后端，事件不因后端而异</li><li>后端拒绝旧 on-disk 格式（pre-release 无兼容承诺）；SQLite 用单调 <code>SCHEMA_VERSION</code> 管理迁移</li><li><code>dsh-session</code> 的 <code>SESSION_FORMAT_VERSION</code> 保持 0：只有结构格式变化才 bump</li><li><strong><code>ignorable: true</code> 机制</strong>：日志事件缺省&quot;必须理解&quot;——不认识的事件拒绝重建；只有带 ignorable 标记的事件允许旧版本跳过</li></ul><p>配套的 <code>ctx.sessionQuery</code>（sqlite 全文检索、游标世代）与 <code>ctx.sessionProjections</code>（状态折叠单元 + 水位检查点 + 冷读取阶梯：缓存行 + 持久化尾部回放——<strong>列表读取永远不需要加载完整日志</strong>）。</p><h2 id="_5-测试体系-分层分明" tabindex="-1">5. 测试体系：分层分明 <a class="header-anchor" href="#_5-测试体系-分层分明" aria-label="Permalink to &quot;5. 测试体系：分层分明&quot;">​</a></h2><p><code>package.json</code> 的测试脚本（结合 <code>docs/testing.md</code>）：</p><table tabindex="0"><thead><tr><th>层</th><th>命令</th><th>什么</th></tr></thead><tbody><tr><td>单元</td><td><code>pnpm run test</code></td><td>vitest，每文件 100% 覆盖率门（CI 用 <code>test:coverage</code>）</td></tr><tr><td>快照</td><td><code>pnpm run test:snapshot</code></td><td><strong>keyless ACP/headless 回放</strong> vs 预期输出</td></tr><tr><td>真实 API</td><td><code>pnpm run test:e2e</code></td><td>需 <code>DEEPSEEK_API_KEY</code>，无 key 自动跳过</td></tr><tr><td>Web</td><td><code>pnpm run test:web</code></td><td>构建后浏览器测试 + 快照 + 压力/性能配置</td></tr><tr><td>Windows</td><td><code>check:windows-wine</code></td><td>Wine 跑 Windows 门（仅 CI 拥有该信号）</td></tr></tbody></table><p>核心纪律（<code>packages/AGENTS.md</code>）：</p><blockquote><p><strong>产品可见的插件必须有一个非平凡的 REAL-composition 测试</strong>：通过 Loader 和真实 app/进程启动 test-only 的 <code>cordis.yml</code>，只 mock 外部服务与不确定输入，断言模型可见/持久/用户可见输出。手工 <code>ctx.plugin(...)</code> 套件不充分。</p></blockquote><blockquote><p><strong>每个非平凡的产品可见行为变更都必须新增或更新一个 keyless snapshot</strong>，通过真实可运行的 example 产生。包测试、e2e-only 断言、mock-only fixture 不能替代组装后的应用 transcript。</p></blockquote><p>以及&quot;测试描述行为，不是正确性&quot;——改行为连同测试一起改，并解释为什么。</p><h2 id="_6-vendored-cordis-拥有你的框架层" tabindex="-1">6. Vendored Cordis：拥有你的框架层 <a class="header-anchor" href="#_6-vendored-cordis-拥有你的框架层" aria-label="Permalink to &quot;6. Vendored Cordis：拥有你的框架层&quot;">​</a></h2><p><code>vendor/README.md</code> 是最值得读的工程文档之一：9 个 vendored 包，<strong>18 条本地修改日志</strong>，每条都记录&quot;改了什么 + 为什么 + 测试覆盖&quot;。摘两条最有教育意义的：</p><ul><li><strong><code>cordis/src/fiber.ts</code> 生命周期加固</strong>（修改 #6）：修复三个重入式资源释放缺口——setup 内触发的 unload 必须等待 setup 与所有清理完成；异步 cleanup 在静默前保持 owner 可见；卸载期间拒绝创建 effect。这是&quot;插件框架的 teardown 是地狱级并发问题&quot;的活教材</li><li><strong>Include 的串行化子树变更</strong>（修改 #12）：两个并发 apply 交错导致 rollback 挂起同一 apply 造成死锁（exit 13 无诊断）——修法是<strong>每个 Include 一个队列</strong>串行化所有子树变更</li></ul><p>为什么 vendor 而不是 npm 依赖？README 开头说得直白：<strong>让 harness 完全拥有自己的框架层（可审计、可补丁、固定版本）</strong>。全部重命名进 <code>@deepseek-ai</code> scope，<code>linkWorkspacePackages</code> 让保留的上游 semver 范围解析到这些固定 workspace。</p><h2 id="_7-运行时不变量-把-宪法-写成代码" tabindex="-1">7. 运行时不变量：把&quot;宪法&quot;写成代码 <a class="header-anchor" href="#_7-运行时不变量-把-宪法-写成代码" aria-label="Permalink to &quot;7. 运行时不变量：把&quot;宪法&quot;写成代码&quot;">​</a></h2><p><code>packages/runtime-diagnostics/invariants</code> 提供 <code>ctx.invariants</code>：<strong>包自有不变量注册表</strong>。每个包注册 <code>./invariant</code> 检查：</p><ul><li>检查<strong>事件/数据关系</strong>（如 agent-loop 的&quot;请求 = 日志纯函数&quot;），而不是服务/方法存在性</li><li>没有可检查关系的包必须给出&quot;无运行时不变量的理由&quot;，否则 fail</li><li>失败标注所属包</li></ul><p>这是把 AGENTS.md 里的纪律（&quot;模型可见 ⟺ 已记录&quot;、&quot;注册即副作用&quot;）变成<strong>执行的 gate</strong>，而不是靠人肉 review。</p><h2 id="_8-约定即生产力-值得抄进简历的纪律" tabindex="-1">8. 约定即生产力：值得抄进简历的纪律 <a class="header-anchor" href="#_8-约定即生产力-值得抄进简历的纪律" aria-label="Permalink to &quot;8. 约定即生产力：值得抄进简历的纪律&quot;">​</a></h2><p>从根 AGENTS.md 提炼最可迁移的几条：</p><ol><li><strong>注册即副作用</strong>：一切贡献走 <code>ctx.effect()</code>/<code>ctx.on()</code>，<code>register()</code> 返回 disposer</li><li><strong>fail loud</strong>：错误配置在加载时自包含地报错，绝不静默跳过缺失的引用</li><li><strong>跨边界 id 品牌化</strong>：<code>Branded&lt;B&gt;</code> 类型，绝不裸 string</li><li><strong>信任同进程类型边界，校验其余</strong>：parser/config、queued、模型/工具 JSON、durable/file、worker、process、wire 七类边界必须运行时校验</li><li><strong>显式优于隐式</strong>：defaulting 是 owning 实现里显式的 <code>resolve(request): Spec</code> 步骤，不是藏在 <code>run()</code> 里的 <code>?? default</code></li><li><strong>无硬编码 tunable</strong>：部署相关的选择必须是可 patch 的 Config 字段；协议常量、外部规范、安全不变量保持固定</li><li><strong>空 catch 必须说明吞掉什么</strong>；try 保持单语句</li><li><strong>prefer symmetry</strong>：并行值不对称通常意味着漏了提取</li><li><strong>Agent Note</strong>：每个非平凡变更带一条决策记录（why + 放弃什么 + 验证要求），归档即冻结</li><li><strong>docs 是 tier 结构</strong>：每个事实只有一个家，其余位置链接</li></ol><h2 id="_9-面试要点" tabindex="-1">9. 面试要点 <a class="header-anchor" href="#_9-面试要点" aria-label="Permalink to &quot;9. 面试要点&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">面试要点 1：219 个包怎么防依赖腐化？</p><p>knip（未用导出检测）+ 工作区约束 + 每包 invariant 注册 + 构建产物不变式检查 + 克隆检测（jscpd）。依赖是显式声明的，peer 关系被 machine gate 检查。</p></div><div class="tip custom-block"><p class="custom-block-title">面试要点 2：为什么双编译面而不是两个包？</p><p>同一批 client 包要同时给 Node（SSR/测试）和浏览器用。tsdown 的 workspace 模式让 host pass 产 Node 入口、client pass 产浏览器工件，共享同一份源码与类型。</p></div><div class="tip custom-block"><p class="custom-block-title">面试要点 3：为什么&quot;产品可见插件必须 REAL-composition 测试&quot;？</p><p>单元测试测的是孤立行为；agent 产品的正确性在<strong>组装后的事件流</strong>里。通过真实 Loader + 真实 app 进程跑 test-only cordis.yml，才能断言&quot;模型可见输出&quot;与&quot;持久输出&quot;。</p></div><div class="tip custom-block"><p class="custom-block-title">面试要点 4：快照测试为什么 keyless？</p><p>真实 API 测试需要 key、不稳定、贵。keyless 回放（llm-replay provider）用固定模型输出重放 transcript，断言组装后的确定性输出——模型行为与产品行为分离测试。</p></div><p>下一篇是<a href="/interview/patterns">面试冲刺</a>：把八章的设计模式提炼成可迁移的手册。</p>`,44)])])}const g=s(a,[["render",r]]);export{b as __pageData,g as default};
